/bin/bash -lc "menv python -c 'from hera.analysis import open_run,resolve_channels,current_channel,sdh_fft; from scipy.signal import find_peaks; import numpy as np
for rid in (6,7):
 r=open_run(\"data/\"+str(rid)); ch=resolve_channels(r.meta); ci=current_channel(ch); cv=next(c for c in ch if c.cid==\"sr1\"); R=(r.col(cv.col)/cv.gain)/(r.col(ci.col)/ci.gain); B=r.col(\"magnet_field\")
 for lo,hi in [(1.5,10),(1.5,5),(2,10)]:
  f,s=sdh_fft(R[:,None],B,b_range=(lo,hi),log=False,nfft=4096,bg_degree=3);p,_=find_peaks(s[0]);p=sorted([j for j in p if 3<f[j]<70],key=lambda j:-s[0,j])[:4];print(rid,lo,hi,[(round(f[j],2),round(s[0,j],1)) for j in p])'"

